-- IA para TDAH: curriculum supplied by the platform owner.
-- Additive only. Draft, no video, no billing or access-policy changes.
-- Commercial tier allocation remains a proposal inside curriculum JSON.
alter table public.trails add column if not exists curriculum jsonb not null default '{}'::jsonb;
alter table public.lessons add column if not exists description text not null default '';
alter table public.lessons add column if not exists planned_material text not null default '';
comment on column public.trails.curriculum is 'Planned curriculum, projects, prerequisites and proposed commercial allocation. Does not grant access.';
comment on column public.lessons.planned_material is 'Name of a planned supporting resource; not a download URL or an existing file.';

do $import_course$
declare
  c jsonb := $curriculum${"id":"ia-para-tdah","name":"IA para TDAH","tagline":"Sua mente cria. Seu sistema entrega.","description":"Forma\u00e7\u00e3o pr\u00e1tica para usar Intelig\u00eancia Artificial na organiza\u00e7\u00e3o, no foco, na criatividade e na execu\u00e7\u00e3o de projetos reais.","summary":"Aprenda a usar a Intelig\u00eancia Artificial para organizar suas ideias, vencer a dificuldade de come\u00e7ar, simplificar tarefas e transformar seus projetos em entregas reais \u2014 no seu ritmo, sem depender de uma rotina perfeita.","status":"em-preparacao","durationMinutes":510,"prerequisites":["N\u00e3o \u00e9 necess\u00e1rio saber programar nem ter experi\u00eancia anterior com IA.","Tenha acesso a um computador ou smartphone.","\u00c9 poss\u00edvel come\u00e7ar com vers\u00f5es gratuitas de ferramentas de IA, respeitando os limites de cada servi\u00e7o."],"audience":"Adultos com TDAH, profissionais criativos, freelancers, empreendedores e estudantes que desejam apoio para organizar e executar suas atividades. N\u00e3o \u00e9 necess\u00e1rio diagn\u00f3stico formal para participar.","notice":"O curso n\u00e3o realiza diagn\u00f3stico, n\u00e3o constitui tratamento e n\u00e3o substitui acompanhamento profissional de sa\u00fade.","projects":[{"name":"Meu Copiloto de IA","description":"O aluno cria um conjunto personalizado de instru\u00e7\u00f5es para receber ajuda com organiza\u00e7\u00e3o, planejamento e divis\u00e3o de tarefas."},{"name":"Da Ideia \u00e0 Entrega","description":"O aluno escolhe um projeto real e utiliza o M\u00e9todo \u00d3RBITA para planejar, executar, revisar e concluir uma entrega."},{"name":"Meu Sistema Pessoal de IA","description":"O aluno integra prompts, rotinas, revis\u00f5es e assistentes em um sistema simples que possa continuar utilizando depois do curso."}],"modules":[{"id":"modulo-01","number":1,"title":"Comece aqui: IA e TDAH sem sobrecarga","level":"iniciante","objective":"apresentar a proposta da forma\u00e7\u00e3o e permitir que o aluno experimente uma primeira aplica\u00e7\u00e3o pr\u00e1tica da IA, sem precisar aprender tudo de uma vez.","proposedPlan":"semente","lessons":[{"id":"ia-tdah-aula-01","number":1,"title":"Bem-vindo ao IA para TDAH","durationMinutes":6,"text":"Conhe\u00e7a a proposta do curso, a metodologia e como a Intelig\u00eancia Artificial poder\u00e1 apoiar atividades do dia a dia e projetos profissionais.","material":"Guia de boas-vindas e mapa da forma\u00e7\u00e3o.","status":"em-preparacao"},{"id":"ia-tdah-aula-02","number":2,"title":"Por que saber o que fazer nem sempre significa conseguir fazer?","durationMinutes":6,"text":"Entenda como dificuldades relacionadas a planejamento, organiza\u00e7\u00e3o, in\u00edcio de tarefas e percep\u00e7\u00e3o do tempo podem interferir na execu\u00e7\u00e3o de atividades. Conhe\u00e7a possibilidades de apoio, sem confundir estrat\u00e9gias pr\u00e1ticas com tratamento.","material":"Mapa das dificuldades de execu\u00e7\u00e3o.","status":"em-preparacao"},{"id":"ia-tdah-aula-03","number":3,"title":"Como aprender sem transformar o curso em outra obriga\u00e7\u00e3o","durationMinutes":6,"text":"Aprenda a utilizar aulas curtas, pequenas experi\u00eancias e revis\u00f5es flex\u00edveis. Descubra como avan\u00e7ar sem precisar manter uma sequ\u00eancia perfeita.","material":"Guia de aprendizagem em pequenas etapas.","status":"em-preparacao"},{"id":"ia-tdah-aula-04","number":4,"title":"Sua primeira vit\u00f3ria com Intelig\u00eancia Artificial","durationMinutes":7,"text":"Escolha uma tarefa que esteja adiando, explique a situa\u00e7\u00e3o \u00e0 IA e pe\u00e7a ajuda para encontrar uma primeira a\u00e7\u00e3o simples e execut\u00e1vel.","material":"Prompt \"Me ajude a come\u00e7ar\".","status":"em-preparacao"}]},{"id":"modulo-02","number":2,"title":"Seu primeiro copiloto de Intelig\u00eancia Artificial","level":"iniciante","objective":"ensinar o aluno a utilizar IA de forma conversacional, pr\u00e1tica e personalizada.","proposedPlan":"broto","lessons":[{"id":"ia-tdah-aula-05","number":5,"title":"Conhecendo o ChatGPT e outras ferramentas","durationMinutes":8,"text":"Entenda o que \u00e9 uma IA conversacional, para que pode ser utilizada e quais s\u00e3o suas principais limita\u00e7\u00f5es.","material":"Guia de ferramentas de IA.","status":"em-preparacao"},{"id":"ia-tdah-aula-06","number":6,"title":"Como conversar com a IA sem precisar escrever prompts perfeitos","durationMinutes":9,"text":"Aprenda a fazer pedidos simples, fornecer contexto e continuar uma conversa at\u00e9 chegar a uma resposta \u00fatil.","material":"10 prompts para iniciantes.","status":"em-preparacao"},{"id":"ia-tdah-aula-07","number":7,"title":"Ensinando a IA a entender seu contexto","durationMinutes":9,"text":"Aprenda a compartilhar objetivos, dificuldades, prefer\u00eancias e restri\u00e7\u00f5es relevantes para receber sugest\u00f5es mais adequadas, sem expor informa\u00e7\u00f5es pessoais desnecess\u00e1rias.","material":"Modelo de contexto pessoal para IA.","status":"em-preparacao"},{"id":"ia-tdah-aula-08","number":8,"title":"Como pedir respostas curtas, claras e objetivas","durationMinutes":9,"text":"Aprenda a configurar o formato das respostas para reduzir excesso de informa\u00e7\u00e3o, dividir orienta\u00e7\u00f5es em etapas e destacar a pr\u00f3xima a\u00e7\u00e3o.","material":"Prompts para respostas sem sobrecarga.","status":"em-preparacao"},{"id":"ia-tdah-aula-09","number":9,"title":"Transformando uma tarefa dif\u00edcil em pequenos passos","durationMinutes":9,"text":"Utilize IA para decompor atividades grandes em a\u00e7\u00f5es menores e identificar um ponto de partida acess\u00edvel.","material":"Prompt \"Quebre essa tarefa para mim\".","status":"em-preparacao"},{"id":"ia-tdah-aula-10","number":10,"title":"Tirando as ideias da cabe\u00e7a com ajuda da IA","durationMinutes":9,"text":"Aprenda a registrar pensamentos soltos por texto ou voz e pedir \u00e0 IA que organize as informa\u00e7\u00f5es por assunto, a\u00e7\u00e3o e prioridade.","material":"Prompt de descarregamento mental.","status":"em-preparacao"},{"id":"ia-tdah-aula-11","number":11,"title":"Personalizando a IA para seu jeito de trabalhar","durationMinutes":9,"text":"Ajuste o tom, a quantidade de informa\u00e7\u00e3o, o formato das listas e a maneira como a IA apresenta sugest\u00f5es.","material":"Modelo de prefer\u00eancias do assistente.","status":"em-preparacao"},{"id":"ia-tdah-aula-12","number":12,"title":"O que a IA faz bem e onde ela pode errar","durationMinutes":9,"text":"Entenda erros, informa\u00e7\u00f5es inventadas, limita\u00e7\u00f5es de mem\u00f3ria e a necessidade de verificar respostas importantes.","material":"Checklist de uso respons\u00e1vel da IA.","status":"em-preparacao"},{"id":"ia-tdah-aula-13","number":13,"title":"Projeto 01: criando seu primeiro copiloto de IA","durationMinutes":9,"text":"Combine as instru\u00e7\u00f5es aprendidas para criar um assistente que ajude a organizar ideias, identificar prioridades e iniciar tarefas.","material":"Template \"Meu Copiloto de IA\".","status":"em-preparacao"}]},{"id":"modulo-03","number":3,"title":"Do caos \u00e0 clareza: organiza\u00e7\u00e3o, foco e execu\u00e7\u00e3o","level":"iniciante a intermedi\u00e1rio","objective":"ensinar aplica\u00e7\u00f5es pr\u00e1ticas de IA para situa\u00e7\u00f5es que frequentemente dificultam a execu\u00e7\u00e3o de tarefas.","proposedPlan":"broto","lessons":[{"id":"ia-tdah-aula-14","number":14,"title":"Organizando pensamentos e tarefas soltas","durationMinutes":9,"text":"Aprenda a transformar uma lista confusa de preocupa\u00e7\u00f5es, ideias e obriga\u00e7\u00f5es em informa\u00e7\u00f5es organizadas e a\u00e7\u00f5es identific\u00e1veis.","material":"Prompt \"Organize minha cabe\u00e7a\".","status":"em-preparacao"},{"id":"ia-tdah-aula-15","number":15,"title":"Como decidir o que fazer primeiro","durationMinutes":9,"text":"Utilize crit\u00e9rios como prazo, import\u00e2ncia, esfor\u00e7o e depend\u00eancias para escolher prioridades realistas com apoio da IA.","material":"Matriz simplificada de prioridades.","status":"em-preparacao"},{"id":"ia-tdah-aula-16","number":16,"title":"Como dividir tarefas que parecem grandes demais","durationMinutes":10,"text":"Aprenda a decompor projetos complexos, identificar obst\u00e1culos e criar passos suficientemente pequenos para serem iniciados.","material":"Prompt de decomposi\u00e7\u00e3o de tarefas.","status":"em-preparacao"},{"id":"ia-tdah-aula-17","number":17,"title":"Como come\u00e7ar quando voc\u00ea est\u00e1 travado","durationMinutes":10,"text":"Experimente estrat\u00e9gias de in\u00edcio, como preparar o ambiente, reduzir o escopo e definir a\u00e7\u00f5es de dois minutos, utilizando a IA para orientar o pr\u00f3ximo passo.","material":"Kit \"Destravar agora\".","status":"em-preparacao"},{"id":"ia-tdah-aula-18","number":18,"title":"Distra\u00e7\u00f5es, hiperfoco e mudan\u00e7as de atividade","durationMinutes":9,"text":"Aprenda a registrar o ponto em que parou, organizar transi\u00e7\u00f5es e criar lembretes para pausas e compromissos.","material":"Checklist de transi\u00e7\u00e3o entre tarefas.","status":"em-preparacao"},{"id":"ia-tdah-aula-19","number":19,"title":"Planejando um dia poss\u00edvel com Intelig\u00eancia Artificial","durationMinutes":10,"text":"Organize compromissos, prioridades, pausas e margens para imprevistos sem ocupar todas as horas dispon\u00edveis.","material":"Prompt \"Planeje meu dia realista\".","status":"em-preparacao"},{"id":"ia-tdah-aula-20","number":20,"title":"Prazos, estimativas e percep\u00e7\u00e3o do tempo","durationMinutes":10,"text":"Use IA para criar estimativas iniciais, separar etapas e prever margens de seguran\u00e7a. Aprenda a ajustar planos com base no tempo realmente utilizado.","material":"Planejador de prazos e estimativas.","status":"em-preparacao"},{"id":"ia-tdah-aula-21","number":21,"title":"Reuni\u00f5es, anota\u00e7\u00f5es e informa\u00e7\u00f5es importantes","durationMinutes":9,"text":"Aprenda a transformar anota\u00e7\u00f5es ou transcri\u00e7\u00f5es autorizadas em resumos, decis\u00f5es e listas de pr\u00f3ximas a\u00e7\u00f5es.","material":"Prompt de resumo de reuni\u00f5es.","status":"em-preparacao"},{"id":"ia-tdah-aula-22","number":22,"title":"Como retomar uma tarefa depois de uma interrup\u00e7\u00e3o","durationMinutes":10,"text":"Crie registros simples do que foi feito, do que falta e de qual a\u00e7\u00e3o deve acontecer em seguida.","material":"Template \"Onde eu parei?\".","status":"em-preparacao"},{"id":"ia-tdah-aula-23","number":23,"title":"Criando uma revis\u00e3o semanal leve","durationMinutes":10,"text":"Utilize IA para revisar pend\u00eancias, reconhecer avan\u00e7os, reorganizar prioridades e planejar a semana seguinte.","material":"Prompt de revis\u00e3o semanal de 10 minutos.","status":"em-preparacao"},{"id":"ia-tdah-aula-24","number":24,"title":"Exerc\u00edcio: organizando uma semana real","durationMinutes":10,"text":"Re\u00fana tarefas e compromissos reais e construa, com a IA, um planejamento semanal flex\u00edvel e ajust\u00e1vel.","material":"Modelo de semana assistida por IA.","status":"em-preparacao"}]},{"id":"modulo-04","number":4,"title":"M\u00e9todo \u00d3RBITA: da ideia ao plano","level":"intermedi\u00e1rio","objective":"ensinar as tr\u00eas primeiras etapas do m\u00e9todo para transformar ideias em projetos execut\u00e1veis.","proposedPlan":"broto","lessons":[{"id":"ia-tdah-aula-25","number":25,"title":"Conhecendo o M\u00e9todo \u00d3RBITA","durationMinutes":9,"text":"Conhe\u00e7a as seis etapas do m\u00e9todo: Orientar, Reduzir, Briefar, Iterar, Testar e Apresentar. Entenda como elas ajudam a organizar um processo de cria\u00e7\u00e3o e entrega.","material":"Mapa visual do M\u00e9todo \u00d3RBITA.","status":"em-preparacao"},{"id":"ia-tdah-aula-26","number":26,"title":"ORIENTAR: escolhendo a dire\u00e7\u00e3o certa","durationMinutes":10,"text":"Aprenda a identificar o objetivo principal de um projeto, sua import\u00e2ncia, o resultado esperado e os crit\u00e9rios de conclus\u00e3o.","material":"Prompt ORIENTAR.","status":"em-preparacao"},{"id":"ia-tdah-aula-27","number":27,"title":"REDUZIR: transformando ideias grandes em vers\u00f5es poss\u00edveis","durationMinutes":9,"text":"Aprenda a limitar o escopo, escolher o essencial e criar uma primeira vers\u00e3o vi\u00e1vel.","material":"Prompt REDUZIR.","status":"em-preparacao"},{"id":"ia-tdah-aula-28","number":28,"title":"BRIEFAR: colocando a ideia em palavras claras","durationMinutes":9,"text":"Utilize IA para organizar contexto, p\u00fablico, objetivos, requisitos e refer\u00eancias em um briefing compreens\u00edvel.","material":"Prompt BRIEFAR.","status":"em-preparacao"},{"id":"ia-tdah-aula-29","number":29,"title":"Como criar um briefing mesmo quando a ideia est\u00e1 confusa","durationMinutes":10,"text":"Aprenda a utilizar perguntas guiadas para transformar pensamentos incompletos em um documento \u00fatil, sem depender de ter todas as respostas desde o in\u00edcio.","material":"Entrevista guiada de briefing com IA.","status":"em-preparacao"},{"id":"ia-tdah-aula-30","number":30,"title":"Transformando o briefing em um plano de execu\u00e7\u00e3o","durationMinutes":10,"text":"Converta o briefing em etapas, microentregas, depend\u00eancias e pr\u00f3ximos passos.","material":"Template de plano de execu\u00e7\u00e3o.","status":"em-preparacao"},{"id":"ia-tdah-aula-31","number":31,"title":"Projeto 02, parte 1: planejando uma entrega real","durationMinutes":10,"text":"Escolha um projeto pessoal ou profissional e aplique as etapas Orientar, Reduzir e Briefar para construir um plano simples.","material":"Workbook \"Da ideia \u00e0 entrega\".","status":"em-preparacao"}]},{"id":"modulo-05","number":5,"title":"M\u00e9todo \u00d3RBITA: da execu\u00e7\u00e3o \u00e0 entrega","level":"intermedi\u00e1rio","objective":"ensinar a utilizar a IA para avan\u00e7ar na execu\u00e7\u00e3o, revisar resultados e concluir entregas.","proposedPlan":"colheita","lessons":[{"id":"ia-tdah-aula-32","number":32,"title":"ITERAR: criando a primeira vers\u00e3o sem buscar perfei\u00e7\u00e3o","durationMinutes":9,"text":"Aprenda a produzir um primeiro rascunho com ajuda da IA e melhorar gradualmente o resultado, evitando gastar toda a energia no planejamento.","material":"Prompt ITERAR.","status":"em-preparacao"},{"id":"ia-tdah-aula-33","number":33,"title":"Melhorando resultados com conversas de refinamento","durationMinutes":9,"text":"Aprenda a identificar problemas, fornecer feedback espec\u00edfico e solicitar corre\u00e7\u00f5es sem recome\u00e7ar todo o trabalho.","material":"Biblioteca de prompts de refinamento.","status":"em-preparacao"},{"id":"ia-tdah-aula-34","number":34,"title":"TESTAR: verificando se o trabalho est\u00e1 realmente pronto","durationMinutes":10,"text":"Utilize crit\u00e9rios de aceita\u00e7\u00e3o, checklists e revis\u00e3o humana para avaliar qualidade, completude e poss\u00edveis erros.","material":"Prompt TESTAR.","status":"em-preparacao"},{"id":"ia-tdah-aula-35","number":35,"title":"APRESENTAR: finalizando e entregando","durationMinutes":10,"text":"Aprenda a organizar o resultado final, preparar uma apresenta\u00e7\u00e3o simples e comunicar a entrega de maneira clara.","material":"Prompt APRESENTAR.","status":"em-preparacao"},{"id":"ia-tdah-aula-36","number":36,"title":"O que fazer quando voc\u00ea trava no meio do projeto","durationMinutes":10,"text":"Aprenda a revisar o escopo, identificar o pr\u00f3ximo passo e retomar o trabalho quando surgirem mudan\u00e7as, d\u00favidas ou perda de ritmo.","material":"Protocolo de retomada de projetos.","status":"em-preparacao"},{"id":"ia-tdah-aula-37","number":37,"title":"Projeto 02, parte 2: concluindo uma entrega real","durationMinutes":10,"text":"Utilize as etapas Iterar, Testar e Apresentar para concluir e revisar um entreg\u00e1vel relacionado ao projeto planejado no m\u00f3dulo anterior.","material":"Checklist de entrega \u00d3RBITA.","status":"em-preparacao"}]},{"id":"modulo-06","number":6,"title":"IA aplicada ao trabalho, aos estudos e \u00e0 criatividade","level":"intermedi\u00e1rio","objective":"demonstrar como a IA pode ajudar em atividades profissionais e acad\u00eamicas reais.","proposedPlan":"colheita","lessons":[{"id":"ia-tdah-aula-38","number":38,"title":"Escrevendo e respondendo mensagens com IA","durationMinutes":10,"text":"Aprenda a elaborar e-mails, mensagens profissionais, respostas a clientes e comunica\u00e7\u00f5es que exigem clareza.","material":"15 prompts de comunica\u00e7\u00e3o.","status":"em-preparacao"},{"id":"ia-tdah-aula-39","number":39,"title":"Criando propostas, or\u00e7amentos e apresenta\u00e7\u00f5es","durationMinutes":10,"text":"Utilize IA para estruturar propostas de servi\u00e7os, organizar informa\u00e7\u00f5es comerciais e preparar apresenta\u00e7\u00f5es para clientes.","material":"Template de proposta profissional.","status":"em-preparacao"},{"id":"ia-tdah-aula-40","number":40,"title":"Transformando ideias criativas em projetos","durationMinutes":10,"text":"Aprenda a utilizar IA para desenvolver conceitos, roteiros, conte\u00fados, campanhas e outros trabalhos criativos sem perder a inten\u00e7\u00e3o original.","material":"Prompt de desenvolvimento criativo.","status":"em-preparacao"},{"id":"ia-tdah-aula-41","number":41,"title":"Organizando demandas de clientes e equipes","durationMinutes":10,"text":"Transforme briefings, mensagens e anota\u00e7\u00f5es em tarefas, prioridades e listas de entreg\u00e1veis.","material":"Prompt de organiza\u00e7\u00e3o de demandas.","status":"em-preparacao"},{"id":"ia-tdah-aula-42","number":42,"title":"Como estudar e aprender utilizando IA","durationMinutes":10,"text":"Aprenda a solicitar explica\u00e7\u00f5es adaptadas, exemplos, perguntas de revis\u00e3o e planos de estudo curtos.","material":"Kit de prompts para estudos.","status":"em-preparacao"},{"id":"ia-tdah-aula-43","number":43,"title":"Revisando e melhorando seu pr\u00f3prio trabalho","durationMinutes":10,"text":"Utilize IA como apoio para revis\u00e3o, organiza\u00e7\u00e3o de feedback e identifica\u00e7\u00e3o de melhorias, verificando criticamente as sugest\u00f5es recebidas.","material":"Prompt de revis\u00e3o profissional.","status":"em-preparacao"}]},{"id":"modulo-07","number":7,"title":"Prompts, assistentes pessoais e automa\u00e7\u00f5es","level":"intermedi\u00e1rio a avan\u00e7ado","objective":"ensinar o aluno a construir um conjunto de ferramentas reutiliz\u00e1veis para reduzir o esfor\u00e7o de planejamento e execu\u00e7\u00e3o.","proposedPlan":"colheita","lessons":[{"id":"ia-tdah-aula-44","number":44,"title":"Criando sua biblioteca pessoal de prompts","durationMinutes":9,"text":"Organize comandos para situa\u00e7\u00f5es recorrentes, como come\u00e7ar uma tarefa, planejar o dia, estudar, escrever e revisar projetos.","material":"Biblioteca inicial de prompts para TDAH.","status":"em-preparacao"},{"id":"ia-tdah-aula-45","number":45,"title":"Criando assistentes especializados","durationMinutes":9,"text":"Aprenda a estruturar instru\u00e7\u00f5es para assistentes com fun\u00e7\u00f5es espec\u00edficas, como planejador, organizador de projetos, tutor e revisor.","material":"Templates de assistentes pessoais.","status":"em-preparacao"},{"id":"ia-tdah-aula-46","number":46,"title":"Criando check-ins com Intelig\u00eancia Artificial","durationMinutes":9,"text":"Desenvolva conversas curtas para iniciar o dia, verificar prioridades, revisar avan\u00e7os e encerrar atividades.","material":"Prompts de check-in di\u00e1rio.","status":"em-preparacao"},{"id":"ia-tdah-aula-47","number":47,"title":"Lembretes, calend\u00e1rios e automa\u00e7\u00f5es simples","durationMinutes":9,"text":"Conhe\u00e7a possibilidades de integra\u00e7\u00e3o com ferramentas de calend\u00e1rio e tarefas. Aprenda quando usar automa\u00e7\u00f5es e como revisar permiss\u00f5es e informa\u00e7\u00f5es compartilhadas.","material":"Guia de automa\u00e7\u00f5es de baixa complexidade.","status":"em-preparacao"},{"id":"ia-tdah-aula-48","number":48,"title":"Projeto 03, parte 1: montando seu sistema pessoal","durationMinutes":10,"text":"Escolha os prompts, assistentes e rotinas que fazem sentido para sua realidade e organize-os em um sistema acess\u00edvel.","material":"Template \"Meu Sistema de IA\".","status":"em-preparacao"}]},{"id":"modulo-08","number":8,"title":"Seu sistema pessoal de IA para TDAH","level":"intermedi\u00e1rio","objective":"consolidar o aprendizado em uma estrutura simples, ajust\u00e1vel e sustent\u00e1vel.","proposedPlan":"colheita","lessons":[{"id":"ia-tdah-aula-49","number":49,"title":"Criando uma rotina que se adapta \u00e0 sua energia","durationMinutes":10,"text":"Aprenda a planejar vers\u00f5es mais leves e mais completas de uma rotina, ajustando prioridades conforme as condi\u00e7\u00f5es do dia.","material":"Planejador de rotina flex\u00edvel.","status":"em-preparacao"},{"id":"ia-tdah-aula-50","number":50,"title":"Como recome\u00e7ar depois de perder o ritmo","durationMinutes":10,"text":"Desenvolva um processo de retomada que permita revisar pend\u00eancias, diminuir o escopo e escolher novamente um primeiro passo.","material":"Prompt \"Vamos recome\u00e7ar\".","status":"em-preparacao"},{"id":"ia-tdah-aula-51","number":51,"title":"Seguran\u00e7a, privacidade e uso consciente da IA","durationMinutes":9,"text":"Aprenda a proteger informa\u00e7\u00f5es pessoais, evitar compartilhar dados sens\u00edveis desnecessariamente e avaliar o uso de ferramentas conectadas.","material":"Checklist de privacidade.","status":"em-preparacao"},{"id":"ia-tdah-aula-52","number":52,"title":"O que a IA n\u00e3o pode fazer por voc\u00ea","durationMinutes":10,"text":"Entenda os limites da intelig\u00eancia artificial em decis\u00f5es importantes, quest\u00f5es de sa\u00fade, diagn\u00f3stico e tratamento. Aprenda a reconhecer situa\u00e7\u00f5es em que \u00e9 necess\u00e1rio buscar apoio humano ou profissional.","material":"Guia de limites e uso respons\u00e1vel.","status":"em-preparacao"},{"id":"ia-tdah-aula-53","number":53,"title":"Como perceber se seu sistema est\u00e1 ajudando","durationMinutes":10,"text":"Aprenda a avaliar o funcionamento do sistema observando indicadores simples, como clareza do pr\u00f3ximo passo, facilidade de retomada e entregas conclu\u00eddas, sem transformar o acompanhamento em mais uma cobran\u00e7a.","material":"Checklist de avalia\u00e7\u00e3o do sistema.","status":"em-preparacao"},{"id":"ia-tdah-aula-54","number":54,"title":"Projeto 03, parte 2: finalizando seu sistema de IA","durationMinutes":9,"text":"Revise seu copiloto, seus prompts, seu processo de organiza\u00e7\u00e3o e sua aplica\u00e7\u00e3o do M\u00e9todo \u00d3RBITA. Elimine elementos desnecess\u00e1rios e mantenha apenas o que for \u00fatil.","material":"Kit final do Sistema Pessoal de IA.","status":"em-preparacao"},{"id":"ia-tdah-aula-55","number":55,"title":"Seu pr\u00f3ximo passo: continuar criando e entregando","durationMinutes":10,"text":"Consolide os aprendizados e defina como utilizar seu sistema em projetos futuros, com revis\u00f5es peri\u00f3dicas e espa\u00e7o para adapta\u00e7\u00f5es.","material":"Plano de continuidade de 30 dias.","status":"em-preparacao"}]}]}$curriculum$::jsonb;
  tid uuid := md5('graao:ia-para-tdah')::uuid;
  mid uuid;
  m jsonb;
  l jsonb;
begin
  if exists (select 1 from public.trails where slug = 'ia-para-tdah' and id <> tid) then
    raise exception 'Course slug already belongs to another ID; review before importing';
  end if;
  insert into public.trails (id, slug, name, description, plan, status, safra, object, position, curriculum)
  values (tid, c->>'id', c->>'name', c->>'summary', 'colheita', 'rascunho', 'uva', 'obj-orbe.svg', 0, c)
  on conflict (id) do nothing;

  for m in select value from jsonb_array_elements(c->'modules') loop
    mid := md5('graao:ia-para-tdah:' || (m->>'id'))::uuid;
    insert into public.modules (id, trail_id, title, description, position, soon)
    values (mid, tid, m->>'title', m->>'objective', (m->>'number')::int, true)
    on conflict (id) do nothing;
    for l in select value from jsonb_array_elements(m->'lessons') loop
      insert into public.lessons (id, module_id, title, position, duration_s, video_key, description, planned_material)
      values (md5('graao:' || (l->>'id'))::uuid, mid, l->>'title', (l->>'number')::int,
              (l->>'durationMinutes')::int * 60, null, l->>'text', l->>'material')
      on conflict (id) do nothing;
    end loop;
  end loop;

  if (select count(*) from public.modules where trail_id = tid) <> 8
     or (select count(*) from public.lessons le join public.modules mo on mo.id=le.module_id where mo.trail_id=tid) <> 55
     or (select sum(duration_s) from public.lessons le join public.modules mo on mo.id=le.module_id where mo.trail_id=tid) <> 30600 then
    raise exception 'Curriculum totals differ from 8 modules / 55 lessons / 30600 seconds';
  end if;
  if not exists (select 1 from public.trails where id=tid and status='rascunho' and curriculum=c)
     or exists (select 1 from public.modules where trail_id=tid and not soon)
     or exists (select 1 from public.lessons le join public.modules mo on mo.id=le.module_id where mo.trail_id=tid and (le.video_key is not null or le.description='' or le.planned_material='')) then
    raise exception 'Course is not a complete draft awaiting production; review existing content';
  end if;
end
$import_course$;
